const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const seasonalCache=new WeakMap();
export function seasonalIllumination(h){
 if(seasonalCache.has(h))return seasonalCache.get(h);
 const d=h.input,a=R+d.altitudeKm,periodS=2*Math.PI*Math.sqrt(a**3/MU),lifeS=Math.max(0,d.missionYears)*YEAR;
 const zeroBetaFraction=Math.asin(clamp(R/a,0,1))/Math.PI;
 const eclipseFraction=beta=>Math.abs(beta)*DEG>=Math.asin(clamp(R/a,0,1))?0:Math.acos(clamp(Math.sqrt(Math.max(0,1-(R/a)**2))/Math.cos(beta*DEG),-1,1))/Math.PI;
 const spanS=Math.min(YEAR,lifeS),starts=[0,Math.max(0,lifeS-spanS)];
 const samples=[];
 for(let season=0;season<25;season++)for(let age=0;age<starts.length;age++){
  const t=starts[age]+spanS*season/24,g=geometry(d,540+t),fraction=eclipseFraction(g.betaDeg);
  samples.push({phase:age?'EOL year':'BOL year',elapsedDays:t/DAY,seasonDays:spanS*season/24,betaDeg:g.betaDeg,eclipseMin:fraction*periodS/60,sunlitFraction:1-fraction,epoch:new Date(Date.parse(d.epoch)+t*1000).toISOString()});
 }
 const ssoRateDegDay=360/365.2422,n=Math.sqrt(MU/a**3),j2=1.5*.00108262668*(R/(a*(1-d.ecc*d.ecc)))**2*n;
 const inclinationCos=-(ssoRateDegDay*DEG/DAY)/j2;
 const epochSun=geometry(d,540).sunECI,sunRaDeg=(Math.atan2(epochSun[1],epochSun[0])/DEG+360)%360;
 const ltanHours=(((d.raanDeg-sunRaDeg)/15+12)%24+24)%24;
 const result={schema:'odc-seasonal-illumination/1',basis:'Cylindrical shadow and the existing J2 / seasonal Sun model; 25 dates in the first and last mission year. Circular-orbit comparison only.',circular:Math.abs(d.ecc)<1e-6,periodMin:periodS/60,ltanAtEpochHours:ltanHours,ssoInclinationDeg:Math.abs(inclinationCos)<=1?Math.acos(inclinationCos)/DEG:null,referenceOrbit:{altitudeKm:550,inclinationDeg:53,ecc:0,lifeYears:5,service:'Live text reference; other customer missions retain their own requirements'},samples,maxSampledEclipseMin:Math.max(...samples.map(s=>s.eclipseMin)),minSampledEclipseMin:Math.min(...samples.map(s=>s.eclipseMin)),conservativeEclipseMin:zeroBetaFraction*periodS/60,analysisSizingBasis:'The conservative beta = 0 circular shadow remains the installed-energy sizing bound. The seasonal samples explain the selected mission and never silently reduce installed storage.',continuousSunClaim:false};
 seasonalCache.set(h,result);return result;
}

