export function architectureProgram(h){
 const identity=designIdentity(h),association=referenceAssociation(h),metadata=association?referenceMetadata(association.id,association.revision):null,family=architectureFamily(h),physical=h.physicalArchitecture;
 const topology=`${family.label}; ${family.solarWingCount} solar wings; ${family.radiatorBankCount} radiator ${family.radiatorBankCount===1?'platform':'banks'}; ${family.payloadLocation==='radiator'?'compute on the moving radiator platform':'compute in the allocated central equipment bay'}`;
 return {schema:'odc-architecture-program/1',revision:architectureProgramRevision,identity,reference:{association,name:association?.name||'Custom study spacecraft',adaptation:metadata?.adaptation||family.evidence,altitudeKm:h.input.altitudeKm,ecc:h.input.ecc,inclinationDeg:h.input.inclinationDeg,missionYears:h.input.missionYears,aiPurpose:h.input.aiPurpose,architectureFamily:family.id,architectureLabel:family.label,physicalTopology:topology,thermalTopology:h.energySystem?.thermal?.topology||family.thermalTopology,thermalRedundancy:h.energySystem?.thermal?.redundancy||'Loop capacity, isolation and common-mode evidence remain open.',boundary:'One self-contained operating spacecraft on one launch; attached deployment; Earth customers; variable mission and life'},selectedCase:{...h.input},missionCase:association?referenceMissionDescription(association.id,h.input.referenceMissionCase):null,physicalArchitecture:physical||null,deploymentGraph:physical?.deployment||null,illumination:seasonalIllumination(h),trade:h.architecture??null,applicability:h.applicability??null,energy:h.energySystem??null,service:h.serviceArchitecture??null,workProducts:architectureWorkProducts,gaps:gapImplementationMap,sources:publicArchitectureReferences,evidenceStatus:'Preliminary analytical implementation; external hardware evidence and review acceptance remain open',scope:'Selectable missions evaluate the installed spacecraft. Explicit hardware inputs or sizing proposals create a new vehicle configuration.'};
}

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'Unassessed';
export function illuminationGraphic(h){
 const r=seasonalIllumination(h),w=800,height=330,left=62,right=768,top=62,bottom=250,x=d=>left+d/Math.max(1,Math.min(YEAR,h.input.missionYears*YEAR)/DAY)*(right-left),y=min=>bottom-min/Math.max(1,r.conservativeEclipseMin)*(bottom-top);
 const grid=[0,.25,.5,.75,1].map(q=>'<path d="M'+left+' '+y(q*r.conservativeEclipseMin)+'H'+right+'" stroke="#334b57"/><text x="52" y="'+(y(q*r.conservativeEclipseMin)+4)+'" text-anchor="end">'+f(q*r.conservativeEclipseMin,0)+'</text>').join('');
 const paths=['BOL year','EOL year'].map((phase,i)=>'<path d="'+r.samples.filter(s=>s.phase===phase).map((s,j)=>(j?'L':'M')+x(s.seasonDays).toFixed(2)+' '+y(s.eclipseMin).toFixed(2)).join(' ')+'" fill="none" stroke="'+(i?'#d3ad71':'#83c8c2')+'" stroke-width="3"/>').join('');
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+w+' '+height+'" role="img" aria-labelledby="mission-light-title mission-light-desc"><title id="mission-light-title">Selected orbit: seasonal eclipse comparison</title><desc id="mission-light-desc">First and last mission year sampled at 25 dates, with a separate conservative zero-beta bound. This is an illumination comparison, not a claim of continuous sunlight.</desc><style>text{fill:#b9ccd6;font:12px system-ui}.title{fill:#eff5f6;font-size:18px;font-weight:650}</style><rect width="800" height="330" rx="12" fill="#13212b"/><text x="28" y="31" class="title">Seasonal illumination · '+f(h.input.altitudeKm,0)+' km / '+f(h.input.inclinationDeg)+'°</text><text x="28" y="51">Eclipse minutes per orbit · LTAN at epoch ≈ '+f(r.ltanAtEpochHours,2)+' h · '+(r.circular?'circular comparison':'circular approximation; eccentric case remains open')+'</text>'+grid+paths+'<path d="M'+left+' '+top+'H'+right+'" stroke="#d69b8f" stroke-dasharray="5 4"/><text x="'+right+'" y="'+(top-9)+'" text-anchor="end">Sizing bound '+f(r.conservativeEclipseMin)+' min</text><text x="62" y="273">0</text><text x="768" y="273" text-anchor="end">'+f(Math.min(YEAR,h.input.missionYears*YEAR)/DAY,0)+' days within sampled year</text><text x="62" y="302" style="fill:#83c8c2">First year</text><text x="174" y="302" style="fill:#d3ad71">Last year</text><text x="290" y="302">Sampled maximum '+f(r.maxSampledEclipseMin)+' min; continuous sunlight is not assumed.</text></svg>';
}
